): ProductMovementMasterRecord {
  const status = cell(row.status).toLowerCase();
  return {
    id: cell(row.id),
    userId: cell(row.userId),
    packingDate: cell(row.packingDate),
    deliverDateTime: cell(row.deliverDateTime) || undefined,
